import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import Brand from "../components/ui/Brand";
import { useApp } from "../lib/AppContext";
const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const navigate = useNavigate();
  const { notify } = useApp();
  const submit = (event) => {
    event.preventDefault();
    navigate("/dashboard");
    notify(`Welcome${email ? `, ${email.split("@")[0]}` : ""} · demo session`);
  };
  return (
    <div className="grid min-h-screen place-items-center bg-[radial-gradient(circle_at_20%_20%,#dcebe2,transparent_35%),#f4f7f4] p-5">
      <div className="w-full max-w-[440px] rounded-2xl border border-gray-100 bg-white p-8 shadow-xl sm:p-10">
        <Link to="/login" className="mb-10 block w-fit">
          <Brand />
        </Link>
        <div className="mb-2 text-[11px] font-bold tracking-widest text-gray-400">ADMINISTRATOR PORTAL</div>
        <h1 className="mb-2 font-['Manrope',sans-serif] text-3xl font-bold">Welcome back</h1>
        <p className="mb-7 text-sm leading-relaxed text-gray-500">Sign in to manage community environmental reports.</p>
        <form onSubmit={submit}>
          <label className="mb-1.5 mt-4 block text-xs font-bold text-gray-700" htmlFor="email">Email address</label>
          <input
            className="h-12 w-full rounded-md border border-gray-200 px-3 text-sm outline-green-700 focus:border-green-700"
            id="email"
            type="email"
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            placeholder="you@gmail.com"
            required
          />
          <label className="mb-1.5 mt-4 block text-xs font-bold text-gray-700" htmlFor="password">Password</label>
          <input
            className="h-12 w-full rounded-md border border-gray-200 px-3 text-sm outline-green-700 focus:border-green-700"
            id="password"
            type="password"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            placeholder="Enter your password"
            required
          />
          <button className="mt-6 flex h-12 w-full items-center justify-center rounded-lg bg-[#185835] px-4 text-sm font-semibold text-white hover:bg-[#12472a]" type="submit">
            Sign in
          </button>
        </form>
      </div>
    </div>
  );
};
export default Login;
